declare(strict_types=1);require_once dirname(__DIR__,2).'/config/database.php';require_once dirname(__DIR__,2).'/includes/auth.php';requireRole(2);$unitId=(int)($_SESSION['unit_id']??0);if(!$unitId){http_response_code(403);exit('Unit kerja Petugas belum ditetapkan.');}$s=$pdo->prepare('SELECT COUNT(*) total,COALESCE(SUM(status_arsip=\'Aktif\'),0) aktif FROM arsip WHERE unit_id=:id');$s->execute(['id'=>$unitId]);$stats=$s->fetch();$s=$pdo->prepare('SELECT no_registrasi,no_surat,perihal,tanggal_surat,status_arsip FROM arsip WHERE unit_id=:id ORDER BY created_at DESC LIMIT 5');$s->execute(['id'=>$unitId]);$items=$s->fetchAll();?>
